      "solution": "<span class=\"eyebrow\">{{category}}</span><h2 id=\"dialog-title\">{{heading}}</h2>{{paragraphs}}<h3>Let’s start here</h3><ul>{{questions}}</ul><p class=\"form-note\">{{note}}</p><button class=\"button\" id=\"solution-contact\">{{cta}} {{arrow}}</button>",
      "faq": "<span class=\"eyebrow\">{{category}} · FAQs</span><h2 id=\"dialog-title\">{{title}}</h2>{{paragraphs}}<button class=\"button\" data-contact>{{cta}} {{arrow}}</button>",
      "scenario": "<span class=\"eyebrow\">{{category}}</span><h2 id=\"dialog-title\">{{title}}</h2><p>{{body}}</p><button class=\"button\" data-contact>Let’s talk {{arrow}}</button>",
      "contactSend": "<span class=\"eyebrow\">Let’s talk</span><h2 id=\"dialog-title\">What would you<br>like to protect?</h2>{{contacts}}<p>{{contactIntro}}</p><form id=\"contact-form\"><label>Your name<input name=\"name\" autocomplete=\"name\" required placeholder=\"What is your name?\" maxlength=\"100\"></label><label>Your email<input type=\"email\" name=\"email\" autocomplete=\"email\" required placeholder=\"name@example.com\" maxlength=\"200\"></label><label>I’m interested in<select name=\"solution\" required><option value=\"\">Choose an option</option>{{options}}<option value=\"other\">Another enquiry</option></select></label><label>Your message<textarea name=\"message\" required rows=\"3\" placeholder=\"Tell us a little about what you need.\" maxlength=\"2500\"></textarea></label><p class=\"form-note\">Sending transmits your details to handle your enquiry, using Resend to deliver the email and Cloudflare for security verification. Read the Privacy policy in the footer. Avoid including identification documents or health information.</p><label class=\"contact-honeypot\" aria-hidden=\"true\">Leave this field empty<input name=\"website\" type=\"text\" tabindex=\"-1\" autocomplete=\"off\" maxlength=\"200\"></label><div class=\"contact-verification\"></div><p class=\"form-status\" role=\"status\" aria-live=\"polite\"></p><button class=\"button\" type=\"submit\" disabled>Send message {{arrow}}</button></form>",
